 5px;\n    }\n\n    &::after {\n      top: 21px;\n    }\n\n    &--open {\n      span {\n        opacity: 0;\n      }\n\n      &::before {\n        top: 13px;\n        transform: rotate(45deg);\n      }\n\n      &::after {\n        top: 13px;\n        transform: rotate(-45deg);\n      }\n    }\n  }\n\n  &__menu {\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    width: min(560px, 100%);\n    gap: 12px;\n  }\n\n  &__link {\n    font-size: 14px;\n    font-weight: 700;\n    line-height: 21px;\n    color: $font-dark;\n    white-space: nowrap;\n    transition: color 0.2s ease;\n\n    &:hover,\n    &--active {\n      color: $primary-hover;\n    }\n  }\n\n  &__actions {\n    display: flex;\n    align-items: center;\n    gap: 16px;\n    flex-shrink: 0;\n  }\n}\n\n.search {\n  display: flex;\n  align-items: stretch;\n\n  &__input {\n    width: 280px;\n    max-width: 42vw;\n    height: 45px;\n    padding: 0 13px;\n    border: 1px solid $border;\n    border-right: none;\n    background: transparent;\n    color: $font-dark;\n    font-size: 14px;\n    font-weight: 300;\n    line-height: 21px;\n    outline: none;\n\n    &::placeholder {\n      color: $text-muted;\n    }\n\n    &:focus {\n      border-color: $border-active;\n    }\n  }\n\n  &__button {\n    height: 45px;\n    padding: 0 36px;\n    background: $primary;\n    color: $font-light;\n    font-size: 14px;\n    font-weight: 700;\n    line-height: 21px;\n    transition: background-color 0.2s ease;\n\n    &:hover {\n      background: $primary-hover;\n    }\n  }\n}\n\n.cart-link {\n  position: relative;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  width: 40px;\n  height: 40px;\n  color: $primary;\n  transition: color 0.2s ease;\n\n  &:hover,\n  &.router-link-active {\n    color: $primary-hover;\n  }\n\n  &__badge {\n    position: absolute;\n    top: 0;\n    right: 0;\n    min-width: 18px;\n    height: 18px;\n    padding: 0 4px;\n    border-radius: 999px;\n    background: $secondary;\n    color: $font-light;\n    font-size: 11px;\n    font-weight: 700;\n    line-height: 18px;\n    text-align: center;\n  }\n}\n\n@media (max-width: 980px) {\n  .header {\n    &__burger {\n      display: block;\n      margin-right: 12px;\n    }\n\n    &__menu {\n      display: none;\n      position: absolute;\n      top: $header-height;\n      left: 0;\n      right: 0;\n      z-index: 40;\n      width: 100%;\n      flex-direction: column;\n      align-items: flex-start;\n      gap: 0;\n      padding: 8px 20px 16px;\n      background: $bg;\n      border-bottom: 1px solid $border;\n\n      &--open {\n        display: flex;\n      }\n\n      li {\n        width: 100%;\n        padding: 10px 0;\n      }\n    }\n  }\n}\n\n@media (max-width: 680px) {\n  .search {\n    &__input {\n      width: 140px;\n      max-width: 36vw;\n    }\n\n    &__button {\n      padding: 0 16px;\n    }\n  }\n}\n\n@media (max-width: 420px) {\n  .header {\n    height: auto;\n    min-height: $header-height;\n    padding: 12px 0;\n  }\n\n  .header__inner {\n    flex-wrap: wrap;\n  }\n\n  .header__actions {\n    width: 100%;\n    justify-content: space-between;\n  }\n\n  .search {\n    flex: 1 1 auto;\n\n    &__input {\n      width: auto;\n      max-width: none;\n      flex: 1 1 auto;\n    }\n  }\n}\n","$bg: #f6f3f3;\n$primary: #403432;\n$primary-hover: #776763;\n$primary-disabled: #c1b4b1;\n$secondary: #5b3a32;\n$footer-bg: #eceaea;\n$font-light: #f4f6f9;\n$font-dark: #343030;\n$text-muted: #9c8e8b;\n$border: #e1e1e1;\n$border-active: #b5b5b5;\n$container-max: 1270px;\n$card-width: 280px;\n$card-image-height: 160px;\n$header-height: 85px;\n$gap: 30px;\n"],"sourceRoot":""}]);
